CREATE OR REPLACE FUNCTION public.save_email_workspace_value(p_field text, p_key text, p_value jsonb) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF; INSERT INTO public.email_workspace_preferences(user_id) VALUES(auth.uid()) ON CONFLICT DO NOTHING; IF p_field='drafts' THEN UPDATE public.email_workspace_preferences SET drafts=CASE WHEN p_value IS NULL OR p_value='null'::jsonb THEN drafts-p_key ELSE jsonb_set(drafts,ARRAY[p_key],p_value,true) END,updated_at=now() WHERE user_id=auth.uid(); ELSIF p_field='organization' THEN UPDATE public.email_workspace_preferences SET organization=CASE WHEN p_value IS NULL OR p_value='null'::jsonb THEN organization-p_key ELSE jsonb_set(organization,ARRAY[p_key],p_value,true) END,updated_at=now() WHERE user_id=auth.uid(); ELSIF p_field='signature_html' THEN UPDATE public.email_workspace_preferences SET signature_html=coalesce(p_value#>>'{}',''),updated_at=now() WHERE user_id=auth.uid(); ELSE RAISE EXCEPTION 'Invalid field'; END IF; END; $$;
REVOKE ALL ON FUNCTION public.save_email_workspace_value(text,text,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.save_email_workspace_value(text,text,jsonb) TO authenticated,service_role;